/* Browsing the living world never grants campaign evidence or skips a case. */
const IslandWorld={
 viewed:-1,stage:null,
 select(id){this.viewed=id;this.stage=null;this.render();const banner=document.querySelector('.campaign-banner');if(banner)banner.hidden=id>=0;let identity=document.querySelector('#island-identity');if(!identity){document.querySelector('.map').insertAdjacentHTML('beforeend','<div id="island-identity"></div>');identity=document.querySelector('#island-identity')}identity.hidden=id<0;if(id>=0){const t=IslandBiomes.themes[id];identity.style.setProperty('--biome',t.accent);identity.innerHTML=`<span>${t.icon}</span><div><small>${t.en}</small><b>${t.name}</b><p>${t.mood}</p></div>`}document.querySelector('#island-canvas')?.setAttribute('aria-label',id<0?'八座特色立體島嶼。選擇目的地可走近觀察建築、工作流程與虛擬居民。':`${IslandBiomes.themes[id].name}，${IslandBiomes.themes[id].mood}。可用下方流程及居民按鈕探索。`)},
 render(){const container=document.querySelector('#district');if(!container)return;if(this.viewed<0){container.innerHTML=`<div class="village-intro"><div><div class="eyebrow">EIGHT ISLANDS · THIRTY-THREE RESIDENTS</div><h2>八座島嶼，八種日常。</h2><p>走近實驗台、晶圓產線、銀行或品牌舞台，觀察不同職能的人如何工作。島上日常是探索線索；案件結論仍要回到合約、訪談與帳目查證。</p></div><button class="primary" id="visit-active-island">前往本案現場 →</button></div><div class="biome-atlas">${IslandBiomes.themes.map((t,id)=>`<button data-village-island="${id}" style="--biome:${t.accent}"><span>${t.icon}</span><div><b>${t.name}</b><small>${t.mood}</small></div><i>↗</i></button>`).join('')}</div>`;document.querySelectorAll('[data-village-island]').forEach(b=>b.onclick=()=>goIsland(+b.dataset.villageIsland));document.querySelector('#visit-active-island').onclick=()=>goIsland(currentStep().island);return}
 const id=this.viewed,t=IslandBiomes.themes[id],p=t.process.find(p=>p[0]===this.stage)||t.process[0];container.style.setProperty('--biome',t.accent);container.innerHTML=`<div class="village-heading"><div><div class="eyebrow">A DAY ON ${t.en}</div><h2>${t.icon} ${t.name}的日常</h2><p>${t.description}</p></div><div class="village-heading-actions"><button class="text-button" id="island-minutes">會議紀錄</button><button class="text-button" id="village-overview">⌂ 返回群島全景</button></div></div><div class="workplace-layout"><div class="process-monitor"><div class="monitor-title"><span class="life-signal"></span>島上工作流程 <small>點步驟，看場景中的位置</small></div><div class="process-path">${t.process.map((v,k)=>`<button data-village-process="${v[0]}" aria-pressed="${p[0]===v[0]}"><small>0${k+1}</small><b>${v[1]}</b><span>→</span></button>`).join('')}</div><div class="process-observation" aria-live="polite"><small>現在觀察 · ${p[1]}</small><p>${p[2]}</p><div class="ask-brief"><b>你為什麼要問</b><p>這一站要確認：${p[3]}</p><b>可以問誰、怎麼開口</b><ul>${IslandBiomes.residents[id].map((r,k)=>`<li><b>${r[0]}</b> · ${r[1]}。先問：「${ResidentStories[id][k][3]}」${window.ResidentMinutes?.person(id,k)?` ${ResidentMinutes.person(id,k).why}`:''}</li>`).join('')}</ul><p>問完按「整理成會議紀錄」。紀錄會留下問題、回答、結論，以及功能（含 DEMPE）、風險、資產，之後拿到案件裡對照。</p></div></div><span class="village-teaching-note">流程為視覺化教學示意，已簡化；場景觀察不會自動成為本案證據。</span></div><div class="village-residents"><div class="monitor-title">虛擬居民 <small>${IslandBiomes.residents[id].length} 位 · 點人物打招呼</small></div><div class="resident-roster">${IslandBiomes.residents[id].map((r,k)=>`<button data-village-resident="${k}">${ResidentAppearance.avatar(id,k)}<span><b>${r[0]}</b><small>${r[1]} · ${ResidentAppearance.get(id,k).gender}性</small><em data-resident-status="${id}:${k}">● ${window.IslandClock?.read().night?'夜間 · ':'日間 · '}${r[2]}</em></span><span class="resident-chat-icon">···</span></button>`).join('')}</div></div></div>`;
 document.querySelectorAll('[data-village-process]').forEach(b=>b.onclick=()=>this.process(id,b.dataset.villageProcess));document.querySelectorAll('[data-village-resident]').forEach(b=>b.onclick=()=>this.resident(id,+b.dataset.villageResident));document.querySelector('#village-overview').onclick=()=>window.TPScene?.home();document.querySelector('#island-minutes').onclick=()=>window.ResidentMinutes?.openIsland(id);
 if(id===6){container.insertAdjacentHTML('beforeend','<div class="audit-pets"><div><b>廣場的小確幸</b><p id="pet-life-status">小花忙著嗅聞、坐下、暴衝與翻肚；橘丸則舔毛、收手趴睡，在路燈下或屋頂打盹。牠們各過各的日常，偶爾碰面玩耍。</p></div><button data-world-pet="dog">🐕 認識小花</button><button data-world-pet="cat">🐈 認識橘丸</button></div>');document.querySelectorAll('[data-world-pet]').forEach(b=>b.onclick=()=>window.TPScene?.pet(b.dataset.worldPet))}
 },
 process(id,key){const p=IslandBiomes.themes[id]?.process.find(p=>p[0]===key);if(!p)return;if(this.viewed!==id)window.TPScene?.focus(id);window.TPScene?.highlightFeature(id,key);this.stage=key;window.TPIslandPage=true;this.render();const box=document.querySelector('#district');box?.classList.add('island-open');document.querySelector('.process-observation')?.scrollIntoView({behavior:'smooth',block:'start'});toast(`正在看：${p[1]}。查證問題在下方。`)},
 resident(id,k){
 const r=IslandBiomes.residents[id]?.[k],d=ResidentStories[id]?.[k];if(!r||!d)return;
 const t=IslandBiomes.themes[id],s=currentStep(),sameInterview=!seasonRecord().complete&&s.kind==='talk'&&s.island===id&&s.speaker===r[0];
 const esc=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
 const rich=x=>esc(x).replace(/\[\[([^\]]+)\]\]/g,'<strong class="resident-clue">$1</strong>');
 const clock=window.IslandClock?.read()||{night:false,text:'15:00',phase:'白晝'};
 const key=id+':'+k;let notebook={};try{notebook=JSON.parse(localStorage.getItem('tp-resident-notebook-v1'))||{}}catch{};
 const read=Array.isArray(notebook[key])?notebook[key].filter(v=>Number.isInteger(v)&&v>=0&&v<4):[];
 const history=[];const prompts=['今天這份工作，實際怎麼做？',d[3],'我該調閱什麼，向誰核對？','有什麼事實可能推翻這項推論？'];
 const answers=[d[1],d[4],d[5],d[6]];
 openModal(`${t.name} · ${r[0]}`,`<div class="resident-visit" style="--biome:${t.accent}"><div class="resident-visit-header">${ResidentAppearance.avatar(id,k,true)}<div><div class="eyebrow">VIRTUAL RESIDENT · 原創虛擬人物</div><h2>${esc(r[0])}</h2><p>${esc(r[1])} · ${esc(t.name)} · ${ResidentAppearance.get(id,k).gender}性</p><p class="resident-look">${ResidentAppearance.get(id,k).hairName} · 小習慣：${ResidentAppearance.get(id,k).habit}</p><span class="resident-time">${clock.text} · ${clock.phase}</span></div></div><p class="resident-biography">${esc(d[0])}</p><div class="resident-conversation" id="resident-conversation"><small>${esc(r[0])} · 現在的生活</small><p>「${rich(clock.night?d[2]:d[1])}」</p></div><div class="resident-thread-status">已探索 <b id="resident-read-count">${new Set(read).size}</b> / 4 個面向 · 追問線索後可解鎖查證，再檢查反證</div><div class="resident-prompts" id="resident-questions"></div><div id="resident-reply" aria-live="polite"></div><div id="resident-next-person"></div>${sameInterview?'<button class="primary" id="resident-case-interview">出示本案案卷，開始正式訪談 →</button>':''}<p class="village-teaching-note">虛構居民的日常口述是待查線索，不會自動變成已核實證據；正式訪談與文據仍由案件主線查證。</p><button class="text-button" id="resident-leave">← 道別，回到島上</button></div>`);
 const renderQuestions=()=>{
 document.querySelector('#resident-questions').innerHTML=prompts.map((q,j)=>{const locked=j===2&&!read.includes(1)||j===3&&!read.includes(2);return `<button data-resident-question="${j}" ${locked||history.includes(j)?'disabled':''}>${locked?'🔒 ':read.includes(j)?'✓ ':''}${esc(q)}</button>`}).join('');
 document.querySelectorAll('[data-resident-question]').forEach(button=>button.onclick=()=>{
 const j=+button.dataset.residentQuestion;if(!read.includes(j))read.push(j);notebook[key]=[...new Set(read)];try{localStorage.setItem('tp-resident-notebook-v1',JSON.stringify(notebook))}catch{}
 if(history.includes(j))return;history.push(j);document.querySelector('#resident-reply').insertAdjacentHTML('beforeend',[j].map(n=>`<div class="resident-player-line">你：${esc(prompts[n])}</div><div class="resident-conversation ${n===3?'resident-counter':''}"><small>${esc(r[0])} · ${['工作現場','追問線索','原始資料','反證與限制'][n]}</small><p>「${rich(answers[n])}」</p></div>`).join(''));
 document.querySelector('#resident-read-count').textContent=new Set(read).size;renderQuestions();
 if(read.includes(3)){const [other,slot]=d[7].split(':').map(Number),next=IslandBiomes.residents[other][slot];document.querySelector('#resident-next-person').innerHTML=`<div class="resident-crosslink"><span>下一位交叉查證對象</span><button id="resident-follow-person">去找 ${esc(next[0])} · ${esc(next[1])} ↗</button><small>保留各人說法，再核對矛盾；口述不等於證據。</small></div>`;document.querySelector('#resident-follow-person').onclick=()=>{window.TPScene?.focus(other);this.resident(other,slot)}}
 });};renderQuestions();window.ResidentChat?.mount({id,k,r,d,t,rich,esc});if(sameInterview)document.querySelector('#resident-case-interview').onclick=openCampaignStep;document.querySelector('#resident-leave').onclick=()=>document.querySelector('#modal').close();
 }

};
const renderCampaignWithVillage=renderSeason;
renderSeason=function(){renderCampaignWithVillage();IslandWorld.render()};
IslandWorld.render();
window.IslandWorld=IslandWorld;
